inline unsigned softmaxProjection(const std::string& mode,const std::vector<one::Fixture>& original){unsigned bad=0;if(mode=="oneSoftmax"){auto fs=upstreamreference::fullUpstream(original);bad=segmentstudy::stages(fs);if(!bad)bad=segmentstudy::productChain(fs);}else if(mode=="oneProjection")bad=segmentstudy::projections(original);else bad=segmentstudy::producers(original);std::printf("summary,%s,failures=%u,cpu_fallback=0,input_mutation=0,finite=1,poison_remaining=0,canary_failures=0,training_updates=0\n",mode.c_str(),bad);return bad?4:0;}
